				ExampleTravelingMerchant.spawnTime = double.MaxValue;
			}
		}

		public override void ClearWorld() {
			ExampleTravelingMerchant.shopItems.Clear();
			ExampleTravelingMerchant.spawnTime = double.MaxValue;
		}

