			drawParams.BarCenter.Y -= 20f;
			drawParams.BarCenter += Main.rand.NextVector2Circular(0.5f, 0.5f) * shakeIntensity * 15f;

			drawParams.IconColor = Main.DiscoColor;

			return true;
		}
	}
}

