			Item.SetWeaponValues(20, 5);

			// Set rarity and value
			Item.SetShopValues(ItemRarityColor.Green2, 10000);
		}

		public override void AddRecipes() {
			CreateRecipe()
				.AddIngredient<ExampleItem>()
				.AddTile<ExampleWorkbench>()
				.Register();
		}
